//! Procedural tile textures.
//!
//! Every pixel here is generated by the code below: there are no image files
//! in this project and nothing is derived from another game's art. The goal is
//! structured pixel art rather than colour noise — blades of grass along the
//! top edge, embedded pebbles in dirt, cracks through stone, grain in wood.

use crate::util::{hash2, Tile};

pub const VARIANTS: usize = 6;

/// Which neighbours are solid, used to pick an edge-aware variant.
#[derive(Clone, Copy, Default)]
pub struct Neighbours {
    pub up: bool,
    pub down: bool,
    pub left: bool,
    pub right: bool,
}

impl Neighbours {
    pub fn mask(self) -> usize {
        (self.up as usize)
            | ((self.right as usize) << 1)
            | ((self.down as usize) << 2)
            | ((self.left as usize) << 3)
    }
}

/// Index into the 16-entry neighbour table for the "shape" of a variant.
/// Variant 0..VARIANTS is the plain fill; the 16 edge cases follow.
pub const VARIANT_COUNT: usize = VARIANTS + 16;

#[derive(Clone, Copy)]
struct Pal {
    dark: [u8; 3],
    base: [u8; 3],
    light: [u8; 3],
    accent: [u8; 3],
}

fn pal(t: Tile) -> Option<Pal> {
    let p = match t {
        Tile::Dirt => Pal {
            dark: [78, 50, 28],
            base: [116, 78, 46],
            light: [146, 102, 62],
            accent: [92, 62, 36],
        },
        Tile::Grass => Pal {
            dark: [46, 88, 30],
            base: [86, 140, 54],
            light: [124, 178, 76],
            accent: [176, 214, 108],
        },
        Tile::Stone => Pal {
            dark: [62, 62, 70],
            base: [96, 96, 104],
            light: [126, 126, 136],
            accent: [78, 78, 88],
        },
        Tile::Wood => Pal {
            dark: [68, 46, 24],
            base: [104, 74, 42],
            light: [136, 100, 60],
            accent: [84, 58, 32],
        },
        Tile::Leaves => Pal {
            dark: [32, 78, 30],
            base: [58, 124, 48],
            light: [96, 168, 66],
            accent: [140, 202, 88],
        },
        Tile::Ore => Pal {
            dark: [58, 58, 68],
            base: [96, 96, 104],
            light: [216, 186, 92],
            accent: [246, 226, 140],
        },
        Tile::Plank => Pal {
            dark: [104, 74, 42],
            base: [150, 112, 66],
            light: [182, 142, 92],
            accent: [126, 92, 54],
        },
        Tile::Sand => Pal {
            dark: [172, 150, 96],
            base: [206, 186, 122],
            light: [230, 214, 156],
            accent: [188, 166, 106],
        },
        Tile::Sandstone => Pal {
            dark: [138, 118, 80],
            base: [176, 154, 106],
            light: [204, 182, 132],
            accent: [152, 130, 90],
        },
        Tile::Snow => Pal {
            dark: [186, 200, 218],
            base: [226, 236, 246],
            light: [250, 252, 255],
            accent: [204, 220, 238],
        },
        Tile::Ice => Pal {
            dark: [104, 152, 196],
            base: [152, 196, 232],
            light: [206, 234, 252],
            accent: [124, 176, 216],
        },
        Tile::Cactus => Pal {
            dark: [38, 84, 38],
            base: [62, 122, 62],
            light: [92, 158, 84],
            accent: [176, 214, 120],
        },
        Tile::Mushroom => Pal {
            dark: [138, 52, 50],
            base: [196, 88, 82],
            light: [238, 140, 130],
            accent: [246, 232, 214],
        },
        Tile::Herb => Pal {
            dark: [58, 104, 40],
            base: [96, 158, 66],
            light: [140, 196, 96],
            accent: [196, 232, 140],
        },
        Tile::Ash => Pal {
            dark: [44, 40, 38],
            base: [78, 68, 64],
            light: [112, 100, 94],
            accent: [150, 120, 96],
        },
        Tile::Hellstone => Pal {
            dark: [58, 22, 20],
            base: [104, 44, 40],
            light: [196, 84, 44],
            accent: [252, 148, 60],
        },
        Tile::GrowingPlant => Pal {
            dark: [52, 100, 36],
            base: [86, 152, 58],
            light: [126, 190, 82],
            accent: [176, 224, 116],
        },
        Tile::Water => Pal {
            dark: [24, 76, 140],
            base: [34, 96, 168],
            light: [72, 148, 214],
            accent: [186, 228, 252],
        },
        _ => return None,
    };
    Some(p)
}

#[inline]
fn put(buf: &mut [[u8; 4]], aw: usize, x: i32, y: i32, c: [u8; 3]) {
    if x < 0 || y < 0 || x as usize >= aw || y >= 16 {
        return;
    }
    let i = (y as usize * aw) + x as usize;
    buf[i] = [c[0], c[1], c[2], 255];
}

#[inline]
fn jitter(c: [u8; 3], amount: f32) -> [u8; 3] {
    [
        (c[0] as f32 + amount).clamp(0.0, 255.0) as u8,
        (c[1] as f32 + amount).clamp(0.0, 255.0) as u8,
        (c[2] as f32 + amount).clamp(0.0, 255.0) as u8,
    ]
}

/// Structured per-tile texture. `v` is the plain variant index, `edge` is the
/// neighbour mask when drawing an edge-aware variant.
pub fn draw_tile(buf: &mut [[u8; 4]], aw: usize, ox: usize, t: Tile, v: usize, edge: Option<Neighbours>) {
    let p = match pal(t) {
        Some(p) => p,
        None => return,
    };
    let col = |c: [u8; 3]| c;
    let h = |x: i32, y: i32| hash2(x + v as i32 * 71, y + t.index().unwrap_or(0) as i32 * 37, 9001);

    // base fill with a gentle two-tone mottle so it isn't flat
    for py in 0..16i32 {
        for px in 0..16i32 {
            let n = h(px, py);
            let c = if n < 0.30 {
                p.dark
            } else if n > 0.76 {
                p.base
            } else {
                col(p.base)
            };
            let j = (h(px * 7, py * 3) - 0.5) * 10.0;
            put(buf, aw, ox as i32 + px, py, jitter(c, j));
        }
    }

    match t {
        Tile::Grass => {
            // blades along the top; the mask decides whether we show them
            let show_top = edge.map(|e| !e.up).unwrap_or(true);
            if show_top {
                for px in 0..16i32 {
                    let len = 2 + (h(px, 99) * 4.0) as i32;
                    for k in 0..len {
                        let c = if k == 0 { p.accent } else { p.light };
                        put(buf, aw, ox as i32 + px, k, c);
                    }
                }
            }
            // shaded fringe where grass meets earth
            for px in 0..16i32 {
                if h(px, 55) > 0.72 {
                    put(buf, aw, ox as i32 + px, 5, p.dark);
                }
            }
            // little sprouts
            for i in 0..3 {
                let px = (h(i, 12) * 15.0) as i32;
                let py = 6 + (h(i, 34) * 8.0) as i32;
                put(buf, aw, ox as i32 + px, py, p.accent);
                put(buf, aw, ox as i32 + px, py + 1, p.light);
            }
        }
        Tile::Dirt => {
            // pebbles
            for i in 0..5 {
                let cx = (h(i, 3) * 12.0) as i32 + 2;
                let cy = (h(i, 7) * 12.0) as i32 + 2;
                let r = 1 + (h(i, 11) > 0.6) as i32;
                for dy in -r..=r {
                    for dx in -r..=r {
                        if dx * dx + dy * dy > r * r {
                            continue;
                        }
                        let c = if dy < 0 { p.light } else { p.accent };
                        put(buf, aw, ox as i32 + cx + dx, cy + dy, c);
                    }
                }
            }
        }
        Tile::Stone => {
            // a hairline crack plus chipped facets
            let sx = (h(1, 2) * 10.0) as i32 + 3;
            for k in 0..10 {
                let px = sx + (k as f32 * 0.6 * (h(k, 5) - 0.5) * 4.0) as i32;
                let py = 2 + k;
                put(buf, aw, ox as i32 + px, py, p.dark);
                if h(k, 9) > 0.7 {
                    put(buf, aw, ox as i32 + px + 1, py, p.accent);
                }
            }
            for i in 0..4 {
                let cx = (h(i, 21) * 13.0) as i32 + 1;
                let cy = (h(i, 23) * 13.0) as i32 + 1;
                put(buf, aw, ox as i32 + cx, cy, p.light);
                put(buf, aw, ox as i32 + cx + 1, cy, p.light);
            }
        }
        Tile::Wood => {
            // vertical grain, darker at the edges
            for px in 0..16i32 {
                let t2 = h(px, 4);
                if t2 > 0.74 {
                    for py in 0..16i32 {
                        put(buf, aw, ox as i32 + px, py, p.dark);
                    }
                } else if t2 > 0.62 {
                    for py in 0..16i32 {
                        if h(px, py) > 0.4 {
                            put(buf, aw, ox as i32 + px, py, p.accent);
                        }
                    }
                }
            }
            for py in 0..16i32 {
                if h(3, py) > 0.85 {
                    put(buf, aw, ox as i32 + 0, py, p.dark);
                    put(buf, aw, ox as i32 + 15, py, p.dark);
                }
            }
        }
        Tile::Leaves => {
            // clustered blobs with gaps so foliage reads as airy
            for i in 0..9 {
                let cx = (h(i, 31) * 14.0) as i32 + 1;
                let cy = (h(i, 37) * 14.0) as i32 + 1;
                let c = if h(i, 41) > 0.65 { p.light } else { p.accent };
                put(buf, aw, ox as i32 + cx, cy, c);
                put(buf, aw, ox as i32 + cx + 1, cy, c);
                put(buf, aw, ox as i32 + cx, cy + 1, p.dark);
            }
            // dappled holes
            for i in 0..4 {
                let cx = (h(i, 51) * 15.0) as i32;
                let cy = (h(i, 53) * 15.0) as i32;
                put(buf, aw, ox as i32 + cx, cy, p.dark);
            }
        }
        Tile::Ore => {
            // nuggets with a specular highlight
            for i in 0..6 {
                let cx = (h(i, 61) * 12.0) as i32 + 2;
                let cy = (h(i, 67) * 12.0) as i32 + 2;
                for dy in 0..2 {
                    for dx in 0..2 {
                        put(buf, aw, ox as i32 + cx + dx, cy + dy, p.light);
                    }
                }
                put(buf, aw, ox as i32 + cx, cy, p.accent);
            }
        }
        Tile::Sand => {
            // wind ripples
            for i in 0..3 {
                let y0 = 3 + i * 4;
                let amp = h(i, 71) * 2.0;
                for px in 0..16i32 {
                    let py = y0 + ((px as f32 * 0.6 + amp).sin() * 1.4) as i32;
                    put(buf, aw, ox as i32 + px, py, p.light);
                }
            }
            for i in 0..10 {
                let cx = (h(i, 73) * 15.0) as i32;
                let cy = (h(i, 79) * 15.0) as i32;
                put(buf, aw, ox as i32 + cx, cy, p.accent);
            }
        }
        Tile::Sandstone => {
            // horizontal strata
            for i in 0..3 {
                let y0 = 2 + i * 5;
                for px in 0..16i32 {
                    if h(px, y0) > 0.25 {
                        put(buf, aw, ox as i32 + px, y0, p.dark);
                    }
                }
            }
            for i in 0..5 {
                let cx = (h(i, 83) * 14.0) as i32 + 1;
                let cy = (h(i, 89) * 14.0) as i32 + 1;
                put(buf, aw, ox as i32 + cx, cy, p.light);
            }
        }
        Tile::Snow => {
            // soft drifts with sparkle
            for i in 0..4 {
                let y0 = 2 + i * 4;
                for px in 0..16i32 {
                    let py = y0 + ((px as f32 * 0.4 + h(i, 3) * 6.0).sin() * 1.2) as i32;
                    put(buf, aw, ox as i32 + px, py, p.light);
                }
            }
            for i in 0..5 {
                let cx = (h(i, 91) * 15.0) as i32;
                let cy = (h(i, 97) * 15.0) as i32;
                put(buf, aw, ox as i32 + cx, cy, [255, 255, 255]);
            }
        }
        Tile::Ice => {
            // angular facets
            for i in 0..3 {
                let cx = (h(i, 101) * 10.0) as i32 + 2;
                let cy = (h(i, 103) * 10.0) as i32 + 2;
                for k in 0..6 {
                    put(buf, aw, ox as i32 + cx + k, cy + k / 2, p.light);
                }
            }
            for px in 0..16i32 {
                if h(px, 107) > 0.8 {
                    put(buf, aw, ox as i32 + px, (h(px, 109) * 15.0) as i32, [235, 248, 255]);
                }
            }
        }
        Tile::Cactus => {
            // ribbed centre column with spines
            for py in 0..16i32 {
                put(buf, aw, ox as i32 + 5, py, p.dark);
                put(buf, aw, ox as i32 + 10, py, p.dark);
                put(buf, aw, ox as i32 + 7, py, p.light);
            }
            for py in (1..15).step_by(3) {
                put(buf, aw, ox as i32 + 3, py, p.accent);
                put(buf, aw, ox as i32 + 12, py, p.accent);
            }
        }
        Tile::Mushroom => {
            for py in 0..16i32 {
                for px in 0..16i32 {
                    put(buf, aw, ox as i32 + px, py, p.dark);
                }
            }
            // cap
            for py in 0..7i32 {
                for px in 3..13i32 {
                    let dx = (px - 8) as f32;
                    let dy = (py - 6) as f32;
                    if dx * dx * 0.05 + dy * dy > 9.0 {
                        continue;
                    }
                    put(buf, aw, ox as i32 + px, py, p.base);
                }
            }
            for i in 0..4 {
                let cx = 4 + (h(i, 111) * 8.0) as i32;
                let cy = 1 + (h(i, 113) * 4.0) as i32;
                put(buf, aw, ox as i32 + cx, cy, p.accent);
            }
            // stem
            for py in 7..15i32 {
                put(buf, aw, ox as i32 + 7, py, [232, 224, 208]);
                put(buf, aw, ox as i32 + 8, py, [208, 198, 180]);
            }
        }
        Tile::Herb => {
            for i in 0..4 {
                let bx = 3 + i * 3;
                let tall = 4 + (h(i, 121) * 5.0) as i32;
                for k in 0..tall {
                    let c = if k > tall - 2 { p.accent } else { p.base };
                    put(buf, aw, ox as i32 + bx, 15 - k, c);
                }
                put(buf, aw, ox as i32 + bx - 1, 15 - tall / 2, p.light);
                put(buf, aw, ox as i32 + bx + 1, 15 - tall / 2, p.light);
            }
        }
        Tile::Ash => {
            for i in 0..7 {
                let cx = (h(i, 131) * 15.0) as i32;
                let cy = (h(i, 137) * 15.0) as i32;
                put(buf, aw, ox as i32 + cx, cy, p.accent);
            }
            // faint embers
            for i in 0..2 {
                let cx = (h(i, 139) * 15.0) as i32;
                let cy = (h(i, 149) * 15.0) as i32;
                put(buf, aw, ox as i32 + cx, cy, [214, 96, 48]);
            }
        }
        Tile::Hellstone => {
            // molten veins
            for i in 0..3 {
                let y0 = 3 + i * 5;
                for px in 0..16i32 {
                    let py = y0 + ((px as f32 * 0.8 + h(i, 151) * 5.0).sin() * 1.8) as i32;
                    if h(px, py) > 0.25 {
                        put(buf, aw, ox as i32 + px, py, p.light);
                    }
                }
            }
            for i in 0..4 {
                let cx = (h(i, 157) * 14.0) as i32;
                let cy = (h(i, 163) * 14.0) as i32;
                put(buf, aw, ox as i32 + cx, cy, p.accent);
            }
        }
        Tile::Plank => {
            // two boards and nail heads
            for py in 0..16i32 {
                if py == 7 || py == 8 {
                    for px in 0..16i32 {
                        put(buf, aw, ox as i32 + px, py, p.dark);
                    }
                }
            }
            for px in [2i32, 13] {
                for py in [3i32, 12] {
                    put(buf, aw, ox as i32 + px, py, p.accent);
                }
            }
        }
        Tile::GrowingPlant => {
            for i in 0..3 {
                let bx = 3 + i * 4;
                let tall = 5 + (h(i, 171) * 6.0) as i32;
                for k in 0..tall {
                    let c = if k > tall - 3 { p.accent } else { p.base };
                    put(buf, aw, ox as i32 + bx, 15 - k, c);
                }
                put(buf, aw, ox as i32 + bx - 1, 15 - tall + 2, p.light);
                put(buf, aw, ox as i32 + bx + 1, 15 - tall + 2, p.light);
            }
        }
        Tile::Water => {
            // caustic bands
            for i in 0..3 {
                let y0 = 2 + i * 5;
                for px in 0..16i32 {
                    let py = y0 + ((px as f32 * 0.5 + h(i, 181) * 7.0).sin() * 2.0) as i32;
                    put(buf, aw, ox as i32 + px, py, p.light);
                }
            }
        }
        _ => {}
    }

    // edge shading: darken the sides that touch solid neighbours
    if let Some(e) = edge {
        let oxi = ox as i32;
        if e.up {
            for px in 0..16i32 {
                put(buf, aw, oxi + px, 0, p.dark);
            }
        }
        if e.down {
            for px in 0..16i32 {
                put(buf, aw, oxi + px, 15, p.dark);
            }
        }
        if e.left {
            for py in 0..16i32 {
                put(buf, aw, oxi, py, p.dark);
            }
        }
        if e.right {
            for py in 0..16i32 {
                put(buf, aw, oxi + 15, py, p.dark);
            }
        }
    }
}
